<script>
import modalMixin from '@/mixins/modalMixins';

export default {
  name: 'OrderModal',
  props: {
    order: {
      type: Object,
      default() {
        return {};
      },
    },
  },
  emits: ['update-order'],
  mixins: [modalMixin],
  data() {
    return {
      modal: '',
      tempOrder: {
        products: [],
        user: {},
        total: 0,
        is_paid: false,
      },
    };
  },
  computed: {
    orderProducts() {
      if (Array.isArray(this.tempOrder.products)) {
        return this.tempOrder.products;
      }

      if (this.tempOrder.products && typeof this.tempOrder.products === 'object') {
        return Object.values(this.tempOrder.products);
      }

      return [];
    },
  },
  watch: {
    order: {
      immediate: true,
      deep: true,
      handler() {
        const isPaid = (
          this.order.is_paid === true
          || this.order.is_paid === 1
          || this.order.is_paid === '1'
          || this.order.is_paid === 'true'
        );

        this.tempOrder = {
          products: [],
          user: {},
          total: 0,
          ...this.order,
          is_paid: isPaid,
        };
      },
    },
  },
};
</script>

